// Cloudflare Worker entry for the web app.
//
// Everything is served by the OpenNext build of the Next.js app, except
// /api/* — REST calls and the /api/realtime WebSocket upgrade — which go to
// the API Worker over the `API` service binding. Browser and API therefore
// share one origin, exactly like the self-hosted build's Next.js rewrite:
// the httpOnly session cookie stays first-party and no CORS is involved.
// A service binding is an internal call (no public hop, no extra latency).
//
// @ts-expect-error -- generated by `opennextjs-cloudflare build`
import { default as openNext } from "./.open-next/worker.js";

interface Env {
  API: { fetch(request: Request): Promise<Response> };
  ASSETS: { fetch(request: Request): Promise<Response> };
}

export default {
  async fetch(request: Request, env: Env, ctx: unknown): Promise<Response> {
    const { pathname } = new URL(request.url);
    if (pathname === "/api" || pathname.startsWith("/api/")) {
      return env.API.fetch(request);
    }
    return openNext.fetch(request, env, ctx);
  },
};
